# Homebrew formula for GALA, generated by tools/install/render_packaging.sh
# from the release's checksums-sha256.txt. It belongs in a tap repository
# (martianoff/homebrew-gala, as Formula/gala.rb).
class Gala < Formula
  desc "Functional programming language that transpiles to Go"
  homepage "https://gala.fyi"
  version "0.101.0"
  license "Apache-2.0"

  on_macos do
    on_arm do
      url "https://github.com/martianoff/gala/releases/download/0.101.0/gala-darwin-arm64"
      sha256 "67ee773d25722870ee7fd6fb1b573e92e337fa85ee8372ea7837b2dacfd41119"
    end
    on_intel do
      url "https://github.com/martianoff/gala/releases/download/0.101.0/gala-darwin-amd64"
      sha256 "91d794addd377838720c8e7467ce6bb84fcdae93aa5d1ea8caacc77ee37aea1d"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/martianoff/gala/releases/download/0.101.0/gala-linux-arm64"
      sha256 "19881ff2e50e565c31b0a971ff0cdeba79ba6037f02531f72c16f7bd4e59894f"
    end
    on_intel do
      url "https://github.com/martianoff/gala/releases/download/0.101.0/gala-linux-amd64"
      sha256 "f913fbacb046c68782cfbe06b9dc9607a75ec81dc9466add818454abb6494883"
    end
  end

  livecheck do
    url :stable
    strategy :github_latest
  end

  # GALA compiles programs through the Go toolchain.
  depends_on "go"

  def install
    bin.install Dir["gala-*"].first => "gala"
  end

  test do
    assert_match "GALA version #{version}", shell_output("#{bin}/gala version")
  end
end
